'use strict';
Kit.suite(({ok})=>{
 const t=T,P=t.P,G=t.G,R=t.roadGuide,C=t.companyRules;
 Kit.begin('soldier',83);Kit.clear();Kit.world();
 const old={critters:t.W.critters,sites:t.W.sites,reach:t.Router.reach,days:t.Router.days,forecast:t.MonsterRegions.forecast,dangerInSight:window.dangerInSight,campSpot:window.campSpot,supplyLand:window.supplyLand};
 try{
  ok(!R.save()&&!C.recover,'optional guidance has no target or recovery plan in untouched saves');
  t.Router.reach=()=>true;t.Router.days=()=>.1;t.MonsterRegions.forecast=()=>({word:'Even'});
  let visible=true;
  const c=Object.assign(new t.Herd(),{id:'deer',n:2,x:P.x+80,y:P.y,hx:P.x+80,hy:P.y});c.memberVisible=()=>visible;
  const m={x:P.x+20,y:P.y},far={x:P.x+80,y:P.y};t.HERD_FLOCK.set(c,{m:[far,m]});t.W.critters=[c];
  const site=(i,type,x,known=true)=>({i,type,x:P.x+x,y:P.y,known:()=>known,cleared:false});
  const camp=site(901,'camp',50),ruin=site(902,'ruins',60),hidden=site(903,'hideout',1,false);t.W.sites=[hidden,camp,ruin];
  let options=R.options();ok(options.length===3&&options[0].x===m.x,'three available choices include the nearest visible individual, not its herd centre');
  ok(options[1].site===camp.i&&options[2].site===ruin.i&&options.every(g=>Math.abs(g.hours-2.4)<1e-8&&g.risk==='Even'),'known sites show route-time and area-danger estimates');
  const gold=P.gold,xp=P.xp,x=P.x,tx=P.tx;R.track(0);
  ok(P.x===x&&P.tx===tx&&P.gold===gold&&P.xp===xp&&!P.quests.length,'tracking cannot move, fight, create a quest or award loot');
  m.x+=10;R.next=0;ok(R.goal().x===m.x,'a tracked visible individual updates its position');
  visible=false;const last=R.goal().x;m.x+=300;R.next=0;ok(R.goal().x===last,'lost wildlife stays at the last seen point instead of revealing fog');
  const saved=JSON.parse(JSON.stringify(R.save()));R.reset();t.Saves.loadOf('roadGuide',saved);ok(R.goal().x===last&&!R.animal,'save/load retains a last-seen waypoint without a live hidden animal reference');
  visible=false;options=R.options();ok(!options.some(g=>g.kind==='hunt'),'invisible animals are never offered');
  ruin.looted=true;camp.cleared=true;ok(R.options().length===0,'searched ruins and cleared camps are not offered again');
  ruin.looted=false;camp.cleared=false;t.Router.reach=()=>false;ok(!R.options().length,'unreachable sites are excluded');t.Router.reach=()=>true;
  R.options();ok(R.track(0),'a discovered camp can be tracked');camp.cleared=true;ok(!R.goal(),'a cleared target removes its obsolete marker');camp.cleared=false;
  t.openRoadGuide();ok(G.mode==='roadguide'&&t.panel.querySelectorAll('.rcard').length===3&&t.panel.querySelector('[data-nav="back"]')&&t.panel.querySelector('[data-nav="close"]'),'guide uses framed choices and standard back/exit navigation');
  ok(t.panel.querySelectorAll('.rc-art [data-ui-icon]').length===3&&t.panel.textContent.includes('Hunt wildlife')&&t.panel.textContent.includes('Clear a camp')&&t.panel.querySelectorAll('[data-act="road-track"]').length===2,'guide renders real titled choices, transparent icons and tracking buttons');
  t.act('road-close');t.questTrackHUD();ok(G.mode==='world'&&document.querySelector('#qtrack [data-act="road-open"]'),'world HUD opens the optional guide without a quest');
  window.dangerInSight=()=>'';window.campSpot=()=>({x:P.x,y:P.y,across:false});window.supplyLand=()=>({desert:false,frost:false,well:true,water:false,rough:false});
  t.playerInventory.add('good','grain',50);P.stay=null;P.siege=null;P.raid=null;P.camp=null;P.bsta=30;G.speed=2;G.paused=true;G.chase=G.follow=G.pitch=null;P.tx=P.ty=null;
  const estimate=t.roadRestInfo();ok(estimate.rate===20&&estimate.hours===3.5&&!estimate.why,'rest shows the actual supplied camp recovery estimate');
  ok(C.beginRecovery()&&C.recover&&P.camp&&G.speed===4&&!G.paused,'one action uses the real camp and starts accelerated recovery');
  const restSave=C.save();C.reset(restSave);ok(C.recover,'explicit recovery survives save/load with journey automation disabled');
  P.bsta=100;C.frame(2);ok(!C.recover&&G.speed===2&&P.camp&&!P.camp.pack,'recovery restores speed and leaves camp for an explicit packing order');
  P.bsta=20;C.beginRecovery();window.dangerInSight=()=> 'bandits';C.frame(2);ok(!C.recover&&G.speed===1,'hostile sightings interrupt the recovery plan and return to normal speed');window.dangerInSight=()=>'';
  C.cancel();P.camp=null;window.campSpot=()=>null;P.tx=P.x+200;const destination=P.tx;
  ok(!C.beginRecovery()&&P.tx===destination&&!C.recover,'an unavailable camp leaves the existing journey intact');
  window.campSpot=()=>({x:P.x,y:P.y,across:false});P.tx=null;C.beginRecovery();t.breakCamp();ok(!C.recover&&!!P.camp.pack&&t.campPackLeft()>0,'rest cannot bypass the existing packing timer');
  t.cancelCampPack();P.bsta=20;t.openRoadGuide();t.act('road-rest');t.openRoadGuide();t.act('road-stop');C.frame(2);
  ok(!C.recover&&G.speed===1&&P.camp&&!P.camp.pack,'Stop recovery keeps camp and respects the selected normal speed');
  t.act('road-close');P.camp=null;C.cancel();window.campSpot=()=>({x:P.x+200,y:P.y,across:false});G.speed=2;
  ok(C.beginRecovery()&&G.pitch&&!P.camp&&G.speed===2,'walking to a campsite does not accelerate time');C.stopRecovery();
  ok(!C.recover&&!G.pitch&&P.tx==null&&G.speed===2,'Stop recovery also cancels an unfinished campsite approach');
  window.supplyLand=()=>({desert:true,well:false,water:false});for(const g of ['water','ale','liquor'])t.goodTake(g,1e6);
  ok(!C.beginRecovery()&&!C.recover,'dry desert recovery cannot create a plan with no possible stamina recovery');
  window.supplyLand=()=>({desert:false,well:true,water:false});window.campSpot=()=>({x:P.x,y:P.y,across:false});C.beginRecovery();
  window.supplyLand=()=>({desert:true,well:false,water:false});C.frame(2);
  ok(!C.recover&&G.speed===1&&P.camp&&!P.camp.pack,'losing the water needed for recovery ends fast-forward while keeping camp');
 }finally{t.W.critters=old.critters;t.W.sites=old.sites;t.Router.reach=old.reach;t.Router.days=old.days;t.MonsterRegions.forecast=old.forecast;for(const k of ['dangerInSight','campSpot','supplyLand'])window[k]=old[k];R.reset();C.reset();Kit.done()}
});
